-- 0003_add_org_client — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- client: client data (02-architecture §4). Staff see all rows; a client sees its own rows marked
-- visibility = 'client'; partners see nothing until a policy links rows to their assigned jobs or sites.
CREATE TABLE client (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  visibility  text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz
);
CREATE INDEX client_client ON client (client_id);

ALTER TABLE client ENABLE ROW LEVEL SECURITY;
CREATE POLICY client_internal ON client FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY client_client_read ON client FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON client TO ocs_app;
